TypeScript example (fetch-based / node):
import { Redwood } from '@redwood/sdk'
const client = new Redwood({
  transport: {
    connectTimeoutMs: 3000,
    requestTimeoutMs: 30000,
    idleKeepaliveMs: 60000,
    maxConnections: 80,
    enableHttp2: true,
  }
})
// streaming with backpressure: use async iterator and await consumer drain
for await (const chunk of client.stream('rwd/chat')) {
  await consumer.push(chunk) // consumer exposes backpressure promise
}

Go example (net/http + transport tuning):
tr := &http.Transport{
  MaxIdleConns: 200,
  MaxIdleConnsPerHost: 20,
  IdleConnTimeout: 60 * time.Second,
  TLSHandshakeTimeout: 3 * time.Second,
  ExpectContinueTimeout: 1 * time.Second,
}
client := &http.Client{Transport: tr, Timeout: 30 * time.Second}
// streaming: use io.Copy with a small buffer and check context cancellation to implement backpressure/resume
